-- Core tables. Design and reasoning: docs/core-tables-and-contracts.md (part A) and docs/decisions.md.
-- Feature tables go in each module's own migrations, not here.
--
-- IDs are UUIDv7 generated by the application (Hibernate @UuidGenerator); Postgres 16 has no
-- built-in v7, so there is deliberately no DEFAULT. Transaction ids stay text (core-banking ids).
-- Text types are varchar, not char(n): ddl-auto=validate rejects char columns mapped to String.
-- updated_at is set by the application (@UpdateTimestamp); the DEFAULT only covers inserts.

-- users: owned by F1 (users module)
CREATE TABLE users (
    id           uuid          PRIMARY KEY,
    cognito_sub  varchar(64)  UNIQUE,
    first_name   varchar(50)  NOT NULL,
    last_name    varchar(50)  NOT NULL,
    email        varchar(254) NOT NULL,
    role         varchar(10)  NOT NULL CHECK (role IN ('ADMIN', 'AGENT')),
    active       boolean      NOT NULL DEFAULT true,
    is_root      boolean      NOT NULL DEFAULT false,
    deleted_at   timestamptz,                               -- "delete user" is a soft delete (D12)
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    version      bigint       NOT NULL DEFAULT 0,
    CHECK (NOT is_root OR role = 'ADMIN'),
    CHECK (NOT is_root OR deleted_at IS NULL),                -- the root admin can't be deleted
    CHECK (deleted_at IS NULL OR NOT active)                  -- a deleted user can't log in
);
CREATE UNIQUE INDEX users_email_uq ON users (lower(email)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX users_single_root_uq ON users (is_root) WHERE is_root;

-- clients: owned by F2 (clients module). Fields from Appendix 2.
-- PII columns are nullable only so erasure can clear them. The two CHECKs require them while not
-- erased and require them cleared once erased_at is set.
-- NULLs don't count towards unique indexes, so an erased client's email and phone can be reused.
CREATE TABLE clients (
    id               uuid          PRIMARY KEY,
    agent_id         uuid         NOT NULL REFERENCES users (id),
    first_name       varchar(50),
    last_name        varchar(50),
    date_of_birth    date,
    gender           varchar(20)
                     CHECK (gender IN ('MALE', 'FEMALE', 'NON_BINARY', 'PREFER_NOT_TO_SAY')),
    email            varchar(254),
    phone            varchar(16)  CHECK (phone ~ '^\+[0-9]{10,15}$'),  -- E.164
    address          varchar(100),
    city             varchar(50),
    state            varchar(50),
    country          varchar(50),
    postal_code      varchar(10),
    identity_status  varchar(20)  NOT NULL DEFAULT 'PENDING'
                     CHECK (identity_status IN ('PENDING', 'VERIFIED', 'FAILED', 'MANUAL_REVIEW')),
    reco_consent     boolean      NOT NULL DEFAULT false,
    erased_at        timestamptz,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    version          bigint       NOT NULL DEFAULT 0,
    CONSTRAINT clients_pii_required CHECK (
        erased_at IS NOT NULL OR (
            first_name IS NOT NULL AND last_name IS NOT NULL AND date_of_birth IS NOT NULL
            AND gender IS NOT NULL AND email IS NOT NULL AND phone IS NOT NULL
            AND address IS NOT NULL AND city IS NOT NULL AND state IS NOT NULL
            AND country IS NOT NULL AND postal_code IS NOT NULL)),
    CONSTRAINT clients_pii_cleared CHECK (
        erased_at IS NULL OR (
            first_name IS NULL AND last_name IS NULL AND date_of_birth IS NULL
            AND gender IS NULL AND email IS NULL AND phone IS NULL
            AND address IS NULL AND city IS NULL AND state IS NULL
            AND country IS NULL AND postal_code IS NULL))
);
CREATE UNIQUE INDEX clients_email_uq ON clients (lower(email));
CREATE UNIQUE INDEX clients_phone_uq ON clients (phone);
CREATE INDEX clients_agent_idx ON clients (agent_id);

-- accounts: owned by F2 (clients module). Fields from Appendix 2.
CREATE TABLE accounts (
    id               uuid           PRIMARY KEY,
    client_id        uuid          NOT NULL REFERENCES clients (id),
    type             varchar(10)   NOT NULL CHECK (type IN ('SAVINGS', 'CHECKING', 'BUSINESS')),
    status           varchar(10)   NOT NULL DEFAULT 'PENDING'
                     CHECK (status IN ('PENDING', 'ACTIVE', 'INACTIVE', 'CLOSED')),
    opening_date     date          NOT NULL,
    initial_deposit  numeric(14,2) NOT NULL CHECK (initial_deposit >= 0),
    currency         varchar(3)    NOT NULL DEFAULT 'SGD' CHECK (currency = 'SGD'),
    branch_id        varchar(20)   NOT NULL,
    source           varchar(15)   NOT NULL DEFAULT 'AGENT' CHECK (source IN ('AGENT', 'RECOMMENDATION')),
    source_ref       uuid,                                    -- e.g. the recommendation id
    closed_at        timestamptz,
    created_at       timestamptz   NOT NULL DEFAULT now(),
    updated_at       timestamptz   NOT NULL DEFAULT now(),
    version          bigint        NOT NULL DEFAULT 0,
    CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL)),
    UNIQUE (id, client_id)                                   -- target of the transactions FK below
);
CREATE INDEX accounts_client_idx ON accounts (client_id);

-- transactions: owned by F3 (transactions module). Fields from Appendix 2 plus account_id.
-- The primary key is the core-banking transaction id, so re-importing a file adds no duplicates.
-- The composite FK makes "account belongs to this client" a database rule, not just an importer check.
CREATE TABLE transactions (
    id             varchar(40)   PRIMARY KEY,
    client_id      uuid          NOT NULL REFERENCES clients (id),
    account_id     uuid          NOT NULL,
    type           varchar(10)   NOT NULL CHECK (type IN ('DEPOSIT', 'WITHDRAWAL')),
    amount         numeric(14,2) NOT NULL CHECK (amount > 0),
    currency       varchar(3)    NOT NULL DEFAULT 'SGD' CHECK (currency = 'SGD'),
    occurred_at    timestamptz   NOT NULL,
    status         varchar(10)   NOT NULL CHECK (status IN ('COMPLETED', 'PENDING', 'FAILED')),
    import_run_id  uuid          NOT NULL,                  -- FK added by F3 with import_runs
    imported_at    timestamptz   NOT NULL DEFAULT now(),
    updated_at     timestamptz   NOT NULL DEFAULT now(),
    FOREIGN KEY (account_id, client_id) REFERENCES accounts (id, client_id),
    UNIQUE (id, client_id)                                   -- target of the cases FK below
);
CREATE INDEX transactions_client_completed_idx
    ON transactions (client_id, occurred_at DESC) WHERE status = 'COMPLETED';
CREATE INDEX transactions_account_idx ON transactions (account_id);

-- cases: owned by F6 (cases module)
-- A disputed transaction must belong to the case's client (composite FK; skipped when transaction_id is NULL).
CREATE TABLE cases (
    id               uuid          PRIMARY KEY,
    client_id        uuid         NOT NULL REFERENCES clients (id),
    agent_id         uuid         NOT NULL REFERENCES users (id),   -- current assignee
    created_by       uuid         NOT NULL REFERENCES users (id),
    category         varchar(25)  NOT NULL
                     CHECK (category IN ('TRANSACTION_DISPUTE', 'SERVICE_COMPLAINT', 'ACCOUNT_ISSUE', 'OTHER')),
    description_enc  text,                                  -- encrypted in the application; NULL once erased
    transaction_id   varchar(40),
    status           varchar(15)  NOT NULL DEFAULT 'OPEN'
                     CHECK (status IN ('OPEN', 'INVESTIGATING', 'RESOLVED')),
    escalated        boolean      NOT NULL DEFAULT false,
    escalated_at     timestamptz,
    sla_started_at   timestamptz  NOT NULL DEFAULT now(),   -- reset on reassignment
    resolved_at      timestamptz,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    version          bigint       NOT NULL DEFAULT 0,
    FOREIGN KEY (transaction_id, client_id) REFERENCES transactions (id, client_id),
    CHECK (category <> 'TRANSACTION_DISPUTE' OR transaction_id IS NOT NULL),
    CHECK ((status = 'RESOLVED') = (resolved_at IS NOT NULL)),
    CHECK (escalated = (escalated_at IS NOT NULL))
);
CREATE INDEX cases_agent_status_idx ON cases (agent_id, status);
CREATE INDEX cases_client_idx ON cases (client_id);
CREATE INDEX cases_sla_due_idx ON cases (sla_started_at) WHERE status <> 'RESOLVED';
